"""Frozen public hand3 transfer, exact physical sampling and sparse cosine features."""
from collections import Counter,defaultdict
from math import sqrt,fsum
from pathlib import Path
from random import Random
import hashlib,json
from vs import corpus,ivtff,generators

HERE=Path(__file__).resolve().parent
EVA=set('acdefghiklmnopqrsty')

def vector(words,feature):
    if feature=='words': c=Counter(words)
    elif feature=='chars':c=Counter(ch for w in words for ch in w)
    else:c=Counter(w[i:i+2] for w in words for i in range(len(w)-1))
    n=sqrt(fsum(v*v for v in c.values()))
    return {k:v/n for k,v in c.items()} if n else {}

def centroid(vectors):
    c=defaultdict(float)
    for v in vectors:
        for k,x in v.items():c[k]+=x/len(vectors)
    n=sqrt(fsum(v*v for v in c.values()))
    return {k:v/n for k,v in c.items()} if n else {}

def cosine(a,b):return fsum(v*b.get(k,0) for k,v in a.items())

def collect():
    paired={e:corpus.split_pages('practice',e)[0] for e in ('zl','it')}
    it={p.id:p for p in paired['it']};meta={};pages={e:[] for e in paired}
    for p in paired['zl']:
        q=it.get(p.id)
        if q is None or (p.hand,p.section,p.language)!=(q.hand,q.section,q.language):continue
        if p.language!='B' or not ((p.section=='S' and p.hand=='3') or (p.section=='H' and p.hand in ('2','3','5'))):continue
        b=p.meta['Q']+':'+p.meta['B']
        own={'hand':p.hand,'section':p.section}
        assert b not in meta or meta[b]==own
        meta[b]=own
        for e,x in [('zl',p),('it',q)]:
            lines=[ivtff.Line(l.id,l.page,l.n,l.unit,l.subtype,[w for w in l.words if not ivtff.uncertain(w) and w and set(w)<=EVA],l.para_start,l.para_end) for l in x.lines if l.unit=='P']
            pages[e].append(ivtff.Page(x.id,x.order,dict(x.meta),lines))
    return pages,meta

def groups(pages):
    out=defaultdict(list)
    for p in pages:out[p.meta['Q']+':'+p.meta['B']].extend(p.words({'P'}))
    return out

def evaluate(words,meta,seed,edition,planted=False):
    sampled={b:Random(f'{edition}/{seed}/{b}').sample(ws,40) for b,ws in sorted(words.items())}
    if planted:
        for b,ws in sampled.items():
            # Fixed explicit hand marker is only a procedure positive control.
            for i in Random(f'plant/{edition}/{seed}/{b}').sample(range(40),4):ws[i]='marker'+meta[b]['hand']
    refs=[b for b in sampled if meta[b]['section']=='S']
    herbal=[b for b in sampled if meta[b]['section']=='H']
    target=next(b for b in herbal if meta[b]['hand']=='3')
    assert set(refs).isdisjoint(herbal)
    rows=[]
    for feature in ('chars','bigrams','words'):
        vs={b:vector(ws,feature) for b,ws in sampled.items()}
        center=centroid([vs[b] for b in refs])
        sims={b:cosine(vs[b],center) for b in herbal}
        value=sims[target];controls=[v for b,v in sims.items() if b!=target]
        rank=1+sum(v>value+1e-12 for b,v in sims.items() if b!=target)+.5*sum(abs(v-value)<=1e-12 for b,v in sims.items() if b!=target)
        within={b:cosine(vs[b],centroid([vs[c] for c in refs if c!=b])) for b in refs}
        rows.append(dict(feature=feature,herbal_similarities=sims,target=target,rank=rank,n_herbal=len(herbal),
                         section_only_midrank=(len(herbal)+1)/2,target_minus_mean_control=value-fsum(controls)/len(controls),
                         within_recipe_leave_one_out=within,cross_minus_mean_within=value-fsum(within.values())/len(within),zero_vectors=sum(not v for v in vs.values())))
    return rows

def main():
    pages,meta=collect();real={e:groups(p) for e,p in pages.items()}
    retained={b for b in meta if all(len(real[e][b])>=40 for e in real)}
    assert len([b for b in retained if meta[b]['hand']=='3' and meta[b]['section']=='H'])==1
    meta={b:v for b,v in meta.items() if b in retained}
    result=dict(plan=json.loads((HERE/'plan.json').read_text()),metadata=meta,inventory={},results=[])
    for e,layout in pages.items():
        layout=[p for p in layout if p.meta['Q']+':'+p.meta['B'] in retained]
        references=[p for p in layout if p.section=='S']
        result['inventory'][e]={b:dict(words=len(real[e][b]),pages=[p.id for p in layout if p.meta['Q']+':'+p.meta['B']==b]) for b in sorted(retained)}
        backgrounds=[('observed',None,groups(layout))]
        for seed in range(401,407):
            copied=generators.g_self_citation(references,layout,seed=seed)
            backgrounds.extend([('copy',seed,groups(copied)),('planted',seed,groups(copied))])
        for scenario,bg,word_groups in backgrounds:
            for seed in range(13,19):
                result['results'].append(dict(edition=e,scenario=scenario,background_seed=bg,sample_seed=seed,
                                            measurements=evaluate(word_groups,meta,seed,e,scenario=='planted')))
    result['sha256']={n:hashlib.sha256((HERE/n).read_bytes()).hexdigest() for n in ('plan.json','run.py')}
    result['input_sha256']={n:hashlib.sha256(Path(n).read_bytes()).hexdigest() for n in ('data/raw/ZL3b-n.txt','data/raw/IT2a-n.txt','vs/generators.py')}
    (HERE/'result.json').write_text(json.dumps(result,indent=2)+'\n')
    print('units',len(meta),'runs',len(result['results']))

if __name__=='__main__':main()
